const p=[...document.querySelectorAll('.showcase .preview')].slice(4).flatMap(x=>[...x.querySelectorAll('acme-context-menu')]);
for(const el of p){const t=el.querySelector('a[href]')??el.querySelector('.text-copy-14');const r=t.getBoundingClientRect();t.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,composed:true,cancelable:true,clientX:r.left+120,clientY:r.top+60}));}
return Promise.all(p.map(async(el,i)=>{await el.updateComplete;const m=el.shadowRoot.querySelector('acme-menu');await m.updateComplete;await m.updateComplete;if(i===0){const row=el.querySelectorAll('acme-menu-item')[1];row.selected=true;await row.updateComplete;}}));

